#!/usr/bin/env node
/**
 * Send a message to a Slack channel (chat.postMessage).
 *
 * Usage:
 *   node send_message.cjs <channel> "<text>" [--thread <thread_ts>]
 *
 *   channel   channel ID (C...) or name (#general)
 *   text      message text (supports Slack mrkdwn formatting)
 *   --thread  reply in a thread, passing the parent message's ts (string)
 *
 * Requires SLACK_TOKEN (bot token with chat:write scope).
 */

const API = 'https://slack.com/api';

function fail(message) {
  process.stderr.write(`Failure: ${message}\n`);
  process.exit(1);
}

async function main() {
  const token = process.env.SLACK_TOKEN;
  if (!token) fail('SLACK_TOKEN environment variable is not set');

  const args = process.argv.slice(2);
  let threadTs;
  const threadIdx = args.indexOf('--thread');
  if (threadIdx !== -1) {
    threadTs = args[threadIdx + 1];
    if (!threadTs) fail('--thread requires a <thread_ts> value');
    args.splice(threadIdx, 2);
  }

  const channel = args[0];
  const text = args.slice(1).join(' ').trim();
  if (!channel || !text) {
    fail('Usage: node send_message.cjs <channel> "<text>" [--thread <thread_ts>]');
  }

  const body = { channel, text };
  if (threadTs) body.thread_ts = threadTs;

  let res;
  try {
    res = await fetch(`${API}/chat.postMessage`, {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${token}`,
        'Content-Type': 'application/json; charset=utf-8',
      },
      body: JSON.stringify(body),
      signal: AbortSignal.timeout(10000),
    });
  } catch (err) {
    fail(`network error: ${err.message}`);
  }

  const data = await res.json().catch(() => ({}));
  if (!res.ok || data.ok !== true) {
    fail(`Slack API error: ${data.error || `HTTP ${res.status}`}`);
  }

  const msg = data.message || {};
  const ts = msg.ts || data.ts || 'unknown';
  const shown = text.length > 200 ? text.slice(0, 200) + '...' : text;
  process.stdout.write(
    `Success: message sent to ${data.channel || channel} (ts=${ts})\n  text: ${shown}\n`,
  );
}

main();

#!/usr/bin/env node
/**
 * List Slack channels visible to the bot (conversations.list).
 *
 * Usage:
 *   node list_channels.cjs [--limit N] [--cursor C] [--types T]
 *
 *   --limit   max channels to return (default 100, max 999)
 *   --cursor  pagination cursor from a previous call
 *   --types   comma-separated conversation types
 *             (default public_channel,private_channel)
 *
 * Requires SLACK_TOKEN (bot token with channels:read scope).
 */

const API = 'https://slack.com/api';

function fail(message) {
  process.stderr.write(`Failure: ${message}\n`);
  process.exit(1);
}

function flagValue(args, name, fallback) {
  const idx = args.indexOf(name);
  if (idx === -1) return fallback;
  const value = args[idx + 1];
  if (value === undefined) fail(`${name} requires a value`);
  return value;
}

async function main() {
  const token = process.env.SLACK_TOKEN;
  if (!token) fail('SLACK_TOKEN environment variable is not set');

  const args = process.argv.slice(2);
  const limit = Number(flagValue(args, '--limit', '100'));
  if (!Number.isInteger(limit) || limit < 1 || limit > 999) {
    fail('--limit must be an integer between 1 and 999');
  }
  const cursor = flagValue(args, '--cursor', '');
  const types = flagValue(args, '--types', 'public_channel,private_channel');

  const params = new URLSearchParams({ types, limit: String(limit) });
  if (cursor) params.set('cursor', cursor);

  let res;
  try {
    res = await fetch(`${API}/conversations.list?${params}`, {
      headers: { Authorization: `Bearer ${token}` },
      signal: AbortSignal.timeout(10000),
    });
  } catch (err) {
    fail(`network error: ${err.message}`);
  }

  const data = await res.json().catch(() => ({}));
  if (!res.ok || data.ok !== true) {
    fail(`Slack API error: ${data.error || `HTTP ${res.status}`}`);
  }

  const channels = data.channels || [];
  const nextCursor = data.response_metadata?.next_cursor || '';
  if (channels.length === 0) {
    process.stdout.write('Success: no channels found\n');
    return;
  }

  const lines = channels.map(
    (c) =>
      `${c.id}  ${c.is_private ? 'private' : 'public'} ${c.name}  ` +
      `member=${c.is_member ? 'yes' : 'no'}  members=${c.num_members ?? '?'}`,
  );
  process.stdout.write(`Success: found ${channels.length} channel(s)\n${lines.join('\n')}\n`);
  if (nextCursor) {
    process.stdout.write(`More results available; pass --cursor ${nextCursor} to continue.\n`);
  }
}

main();

#!/usr/bin/env node
/**
 * Read recent messages from a Slack channel (conversations.history).
 *
 * Usage:
 *   node read_history.cjs <channel> [--limit N] [--oldest TS] [--latest TS] [--cursor C]
 *
 *   channel   channel ID (C...) or name (#general)
 *   --limit   max messages (default 20, max 999)
 *   --oldest  only messages after this ts (string)
 *   --latest  only messages before this ts (string)
 *   --cursor  pagination cursor from a previous call
 *
 * Requires SLACK_TOKEN (bot token with channels:history scope).
 */

const API = 'https://slack.com/api';

function fail(message) {
  process.stderr.write(`Failure: ${message}\n`);
  process.exit(1);
}

function flagValue(args, name, fallback) {
  const idx = args.indexOf(name);
  if (idx === -1) return fallback;
  const value = args[idx + 1];
  if (value === undefined) fail(`${name} requires a value`);
  return value;
}

function sender(m) {
  if (m.bot_id) return `bot:${m.bot_id}`;
  return m.user ? `user:${m.user}` : '?';
}

async function main() {
  const token = process.env.SLACK_TOKEN;
  if (!token) fail('SLACK_TOKEN environment variable is not set');

  const args = process.argv.slice(2);
  const channel = args[0];
  if (!channel) {
    fail('Usage: node read_history.cjs <channel> [--limit N] [--oldest TS] [--latest TS] [--cursor C]');
  }
  const limit = Number(flagValue(args, '--limit', '20'));
  if (!Number.isInteger(limit) || limit < 1 || limit > 999) {
    fail('--limit must be an integer between 1 and 999');
  }
  const oldest = flagValue(args, '--oldest', '');
  const latest = flagValue(args, '--latest', '');
  const cursor = flagValue(args, '--cursor', '');

  const params = new URLSearchParams({ channel, limit: String(limit) });
  if (oldest) params.set('oldest', oldest);
  if (latest) params.set('latest', latest);
  if (cursor) params.set('cursor', cursor);

  let res;
  try {
    res = await fetch(`${API}/conversations.history?${params}`, {
      headers: { Authorization: `Bearer ${token}` },
      signal: AbortSignal.timeout(10000),
    });
  } catch (err) {
    fail(`network error: ${err.message}`);
  }

  const data = await res.json().catch(() => ({}));
  if (!res.ok || data.ok !== true) {
    fail(`Slack API error: ${data.error || `HTTP ${res.status}`}`);
  }

  const messages = data.messages || [];
  const nextCursor = data.response_metadata?.next_cursor || '';
  if (messages.length === 0) {
    process.stdout.write('Success: no messages found\n');
    return;
  }

  const lines = messages.map((m) => {
    const text = String(m.text || '').replace(/\n/g, ' ');
    const truncated = text.length > 300 ? text.slice(0, 300) + '...' : text;
    const replies = m.reply_count ? `  (${m.reply_count} replies)` : '';
    return `[${m.ts}] ${sender(m)}: ${truncated}${replies}`;
  });

  process.stdout.write(
    `Success: ${messages.length} message(s) from ${channel}\n${lines.join('\n')}\n`,
  );
  if (nextCursor) {
    process.stdout.write(`More results available; pass --cursor ${nextCursor} to continue.\n`);
  }
}

main();

