#!/usr/bin/env node
/**
 * Upload a file to a Slack channel (files.upload).
 *
 * Usage:
 *   node upload_file.cjs <channel> <filepath> [--title T] [--comment C]
 *
 * Requires SLACK_TOKEN (bot token with files:write scope).
 */

const fs = require('node:fs');
const path = require('node:path');
const API = 'https://slack.com/api';

const MIME_TYPES = {
  '.txt': 'text/plain',
  '.md': 'text/markdown',
  '.csv': 'text/csv',
  '.json': 'application/json',
  '.pdf': 'application/pdf',
  '.png': 'image/png',
  '.jpg': 'image/jpeg',
  '.jpeg': 'image/jpeg',
  '.gif': 'image/gif',
  '.zip': 'application/zip',
};

function fail(message) {
  process.stderr.write(`Failure: ${message}\n`);
  process.exit(1);
}

function flagValue(args, name, fallback) {
  const idx = args.indexOf(name);
  if (idx === -1) return fallback;
  const value = args[idx + 1];
  if (value === undefined) fail(`${name} requires a value`);
  return value;
}

async function main() {
  const token = process.env.SLACK_TOKEN;
  if (!token) fail('SLACK_TOKEN environment variable is not set');

  const args = process.argv.slice(2);
  const channel = args[0];
  const filepath = args[1];
  if (!channel || !filepath) {
    fail('Usage: node upload_file.cjs <channel> <filepath> [--title T] [--comment C]');
  }
  const title = flagValue(args, '--title', '');
  const comment = flagValue(args, '--comment', '');

  if (!fs.existsSync(filepath)) fail(`file not found: ${filepath}`);
  const stat = fs.statSync(filepath);
  if (stat.size > 100 * 1024 * 1024) {
    fail(`file too large for files.upload: ${filepath} (max 100MB)`);
  }

  const ext = path.extname(filepath).toLowerCase();
  const type = MIME_TYPES[ext] || 'application/octet-stream';

  const form = new FormData();
  form.append('channels', channel);
  form.append('file', new Blob([fs.readFileSync(filepath)], { type }), path.basename(filepath));
  if (title) form.append('title', title);
  if (comment) form.append('initial_comment', comment);

  let res;
  try {
    res = await fetch(`${API}/files.upload`, {
      method: 'POST',
      headers: { Authorization: `Bearer ${token}` },
      body: form,
      signal: AbortSignal.timeout(15000),
    });
  } catch (err) {
    fail(`network error: ${err.message}`);
  }

  const data = await res.json().catch(() => ({}));
  if (!res.ok || data.ok !== true) {
    fail(`Slack API error: ${data.error || `HTTP ${res.status}`}`);
  }

  const file = data.file || {};
  process.stdout.write(
    `Success: uploaded ${file.name || path.basename(filepath)} to ${channel} ` +
      `(file id=${file.id || 'unknown'})\n`,
  );
}

main();

#!/usr/bin/env node
/**
 * Offline smoke tests for the slack-api skill scripts.
 *
 * Runs every script through its validation/failure paths (missing args,
 * missing token, bad flags, missing file, and API/network failure with a
 * fake token) and asserts:
 *   - exit code 1
 *   - stderr starts with "Failure:"
 *   - no stack trace / uncaught exception noise
 *   - no "Success:" on stdout
 *
 * Usage: node test_slack_scripts.cjs
 */

const { spawnSync } = require('node:child_process');
const path = require('node:path');

const scriptsDir = path.join(__dirname, 'slack-api', 'scripts');
const node = process.execPath;

const CASES = [
  { name: 'send_message: no args', file: 'send_message.cjs', args: [] },
  { name: 'send_message: missing token', file: 'send_message.cjs', args: ['C123', 'hello'] },
  { name: 'send_message: fake token (network/API)', file: 'send_message.cjs', args: ['C123', 'hello'], token: 'xoxb-fake' },
  { name: 'send_message: --thread without value', file: 'send_message.cjs', args: ['C123', 'hi', '--thread'], token: 'xoxb-fake' },
  { name: 'list_channels: missing token', file: 'list_channels.cjs', args: [] },
  { name: 'list_channels: bad --limit', file: 'list_channels.cjs', args: ['--limit', 'abc'], token: 'xoxb-fake' },
  { name: 'list_channels: fake token (network/API)', file: 'list_channels.cjs', args: [], token: 'xoxb-fake' },
  { name: 'read_history: no args', file: 'read_history.cjs', args: [] },
  { name: 'read_history: fake token (network/API)', file: 'read_history.cjs', args: ['C123'], token: 'xoxb-fake' },
  { name: 'create_channel: no args', file: 'create_channel.cjs', args: [] },
  { name: 'create_channel: fake token (network/API)', file: 'create_channel.cjs', args: ['test-channel'], token: 'xoxb-fake' },
  { name: 'list_users: fake token (network/API)', file: 'list_users.cjs', args: [], token: 'xoxb-fake' },
  { name: 'upload_file: no args', file: 'upload_file.cjs', args: [] },
  { name: 'upload_file: missing file', file: 'upload_file.cjs', args: ['C123', '/nonexistent/file.txt'], token: 'xoxb-fake' },
  { name: 'upload_file: fake token (network/API)', file: 'upload_file.cjs', args: ['C123', __filename], token: 'xoxb-fake' },
];

let failed = 0;

for (const c of CASES) {
  const env = { ...process.env };
  if (c.token) env.SLACK_TOKEN = c.token;
  else delete env.SLACK_TOKEN;

  const result = spawnSync(node, [path.join(scriptsDir, c.file), ...c.args], {
    encoding: 'utf8',
    env,
    timeout: 15000,
  });

  const problems = [];
  if (result.error) problems.push(`spawn error: ${result.error.message}`);
  if (result.status !== 1) problems.push(`expected exit 1, got ${result.status}`);
  if (!result.stderr.startsWith('Failure:')) problems.push(`stderr must start with 'Failure:', got: ${JSON.stringify(result.stderr.slice(0, 120))}`);
  if (result.stderr.includes('\n    at ')) problems.push('stderr contains a stack trace');
  if (result.stderr.includes('Uncaught')) problems.push('stderr contains an uncaught exception');
  if (result.stdout.includes('Success:')) problems.push('stdout unexpectedly contains Success:');

  if (problems.length > 0) {
    failed += 1;
    console.log(`❌ ${c.name}`);
    for (const p of problems) console.log(`   - ${p}`);
  } else {
    console.log(`✅ ${c.name}`);
  }
}

if (failed > 0) {
  console.log(`\n${failed}/${CASES.length} checks FAILED`);
  process.exit(1);
}
console.log(`\nAll ${CASES.length} checks passed.`);

#!/usr/bin/env node
/**
 * Task-local packager for the slack-api skill.
 *
 * Replicates skill-creator's package_skill.cjs but with a pure-Node ZIP writer
 * (no external `zip` binary required):
 *   1. Validates the skill (SKILL.md frontmatter, hyphen-case name,
 *      single-line description, no unresolved TODOs).
 *   2. Packages slack-api/ into slack-api.skill (a ZIP archive).
 *   3. Self-verifies the archive by re-reading it and decompressing every
 *      entry, comparing bytes and CRC32 against the originals.
 *
 * NOT yet executed: script execution is blocked by the environment's active
 * defense in this session. Run with:  node package_slack_skill.cjs
 */

const fs = require('node:fs');
const path = require('node:path');
const zlib = require('node:zlib');

const SKILL_DIR = path.join(__dirname, 'slack-api');
const OUTPUT = path.join(__dirname, 'slack-api.skill');

// ---------- Validation (mirrors validate_skill.cjs) ----------

function validateSkill(skillPath) {
  const skillMdPath = path.join(skillPath, 'SKILL.md');
  if (!fs.existsSync(skillMdPath)) return 'SKILL.md not found';
  const content = fs.readFileSync(skillMdPath, 'utf8');
  if (!content.startsWith('---')) return 'No YAML frontmatter found';
  const parts = content.split('---');
  if (parts.length < 3) return 'Invalid frontmatter format';
  const frontmatter = parts[1];
  const nameMatch = frontmatter.match(/^name:\s*(.+)$/m);
  const descMatch = frontmatter.match(
    /^description:\s*(?:'([^']*)'|"([^"]*)"|(.+))$/m,
  );
  if (!nameMatch) return 'Missing "name" in frontmatter';
  if (!descMatch) return 'Description must be a single-line string: description: ...';
  const name = nameMatch[1].trim();
  const description = (
    descMatch[1] !== undefined ? descMatch[1]
    : descMatch[2] !== undefined ? descMatch[2]
    : descMatch[3] || ''
  ).trim();
  if (description.includes('\n')) return 'Description must be a single line (no newlines)';
  if (!/^[a-z0-9-]+$/.test(name)) return `Name "${name}" should be hyphen-case`;
  if (description.length > 1024) return 'Description is too long (max 1024)';

  const files = getAllFiles(skillPath);
  for (const file of files) {
    if (fs.readFileSync(file, 'utf8').includes('TODO:')) {
      return `Unresolved TODO in ${path.relative(skillPath, file)}`;
    }
  }
  return null;
}

function getAllFiles(dir, fileList = []) {
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) getAllFiles(full, fileList);
    else fileList.push(full);
  }
  return fileList;
}

// ---------- Minimal ZIP writer (deflate, no compression libs beyond zlib) ----------

const CRC_TABLE = (() => {
  const table = new Int32Array(256);
  for (let n = 0; n < 256; n++) {
    let c = n;
    for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
    table[n] = c;
  }
  return table;
})();

function crc32(buf) {
  let crc = -1;
  for (let i = 0; i < buf.length; i++) {
    crc = CRC_TABLE[(crc ^ buf[i]) & 0xff] ^ (crc >>> 8);
  }
  return (crc ^ -1) >>> 0;
}

function dosDateTime(date) {
  const time = (date.getHours() << 11) | (date.getMinutes() << 5) | (date.getSeconds() >> 1);
  const dateBits = ((date.getFullYear() - 1980) << 9) | ((date.getMonth() + 1) << 5) | date.getDate();
  return { time, date: dateBits };
}

function localHeader(name, crc, csize, usize, time, date) {
  const nameBuf = Buffer.from(name, 'utf8');
  const buf = Buffer.alloc(30 + nameBuf.length);
  buf.writeUInt32LE(0x04034b50, 0);
  buf.writeUInt16LE(20, 4);
  buf.writeUInt16LE(0, 6);
  buf.writeUInt16LE(8, 8);
  buf.writeUInt16LE(time, 10);
  buf.writeUInt16LE(date, 12);
  buf.writeUInt32LE(crc, 14);
  buf.writeUInt32LE(csize, 18);
  buf.writeUInt32LE(usize, 22);
  buf.writeUInt16LE(nameBuf.length, 26);
  buf.writeUInt16LE(0, 28);
  nameBuf.copy(buf, 30);
  return buf;
}

function centralEntry(name, crc, csize, usize, time, date, offset) {
  const nameBuf = Buffer.from(name, 'utf8');
  const buf = Buffer.alloc(46 + nameBuf.length);
  buf.writeUInt32LE(0x02014b50, 0);
  buf.writeUInt16LE(20, 4);
  buf.writeUInt16LE(20, 6);
  buf.writeUInt16LE(0, 8);
  buf.writeUInt16LE(8, 10);
  buf.writeUInt16LE(time, 12);
  buf.writeUInt16LE(date, 14);
  buf.writeUInt32LE(crc, 16);
  buf.writeUInt32LE(csize, 20);
  buf.writeUInt32LE(usize, 24);
  buf.writeUInt16LE(nameBuf.length, 28);
  buf.writeUInt16LE(0, 30);
  buf.writeUInt16LE(0, 32);
  buf.writeUInt16LE(0, 34);
  buf.writeUInt16LE(0, 36);
  buf.writeUInt32LE(0, 38);
  buf.writeUInt32LE(offset, 42);
  nameBuf.copy(buf, 46);
  return buf;
}

function endOfCentral(entries, cdSize, cdOffset) {
  const buf = Buffer.alloc(22);
  buf.writeUInt32LE(0x06054b50, 0);
  buf.writeUInt16LE(0, 4);
  buf.writeUInt16LE(0, 6);
  buf.writeUInt16LE(entries, 8);
  buf.writeUInt16LE(entries, 10);
  buf.writeUInt32LE(cdSize, 12);
  buf.writeUInt32LE(cdOffset, 16);
  buf.writeUInt16LE(0, 20);
  return buf;
}

function buildZip(files) {
  const chunks = [];
  const entries = [];
  let offset = 0;
  const now = new Date();
  const { time, date } = dosDateTime(now);

  for (const file of files) {
    const name = path.relative(SKILL_DIR, file).split(path.sep).join('/');
    const content = fs.readFileSync(file);
    const compressed = zlib.deflateRawSync(content);
    const crc = crc32(content);
    const local = localHeader(name, crc, compressed.length, content.length, time, date);
    entries.push({ name, crc, csize: compressed.length, usize: content.length, time, date, offset });
    chunks.push(local, compressed);
    offset += local.length + compressed.length;
  }

  const cdStart = offset;
  const cdChunks = entries.map((e) =>
    centralEntry(e.name, e.crc, e.csize, e.usize, e.time, e.date, e.offset),
  );
  const cdSize = cdChunks.reduce((sum, c) => sum + c.length, 0);
  const eocd = endOfCentral(entries.length, cdSize, cdStart);
  return Buffer.concat([...chunks, ...cdChunks, eocd]);
}

function verifyZip(zipPath, expectedFiles) {
  const buf = fs.readFileSync(zipPath);
  const eocdOffset = buf.length - 22;
  if (buf.readUInt32LE(eocdOffset) !== 0x06054b50) throw new Error('bad end-of-central-directory signature');
  const totalEntries = buf.readUInt16LE(eocdOffset + 10);
  const cdSize = buf.readUInt32LE(eocdOffset + 12);
  const cdOffset = buf.readUInt32LE(eocdOffset + 16);

  const verified = [];
  let p = cdOffset;
  for (let i = 0; i < totalEntries; i++) {
    if (buf.readUInt32LE(p) !== 0x02014b50) throw new Error(`bad central directory entry ${i}`);
    const method = buf.readUInt16LE(p + 10);
    const crc = buf.readUInt32LE(p + 16);
    const csize = buf.readUInt32LE(p + 20);
    const usize = buf.readUInt32LE(p + 24);
    const nameLen = buf.readUInt16LE(p + 28);
    const extraLen = buf.readUInt16LE(p + 30);
    const commentLen = buf.readUInt16LE(p + 32);
    const localOffset = buf.readUInt32LE(p + 42);
    const name = buf.toString('utf8', p + 46, p + 46 + nameLen);

    const localNameLen = buf.readUInt16LE(localOffset + 26);
    const localExtraLen = buf.readUInt16LE(localOffset + 28);
    const dataStart = localOffset + 30 + localNameLen + localExtraLen;
    const raw = buf.subarray(dataStart, dataStart + csize);
    const content = method === 8 ? zlib.inflateRawSync(raw) : raw;
    if (content.length !== usize) throw new Error(`size mismatch for ${name}`);
    if (crc32(content) !== crc) throw new Error(`CRC32 mismatch for ${name}`);
    const original = fs.readFileSync(path.join(SKILL_DIR, name));
    if (!content.equals(original)) throw new Error(`content mismatch for ${name}`);
    verified.push(name);
    p += 46 + nameLen + extraLen + commentLen;
  }
  if (p !== cdOffset + cdSize) throw new Error('central directory size mismatch');

  const expected = expectedFiles.map((f) => path.relative(SKILL_DIR, f).split(path.sep).join('/')).sort();
  const got = verified.sort();
  if (JSON.stringify(expected) !== JSON.stringify(got)) {
    throw new Error(`archive entry mismatch: expected ${expected.join(', ')} got ${got.join(', ')}`);
  }
  return verified;
}

// ---------- Main ----------

const validationError = validateSkill(SKILL_DIR);
if (validationError) {
  console.error(`❌ Validation failed: ${validationError}`);
  process.exit(1);
}
console.log('✅ Skill is valid!');

const files = getAllFiles(SKILL_DIR).sort();
const zip = buildZip(files);
fs.writeFileSync(OUTPUT, zip);
console.log(`✅ Wrote ${OUTPUT} (${zip.length} bytes, ${files.length} file(s))`);

const verified = verifyZip(OUTPUT, files);
console.log(`✅ Self-verification passed for ${verified.length} entry/entries:`);
for (const name of verified) console.log(`   - ${name}`);

